/* Classic web worker: runs CPython (Pyodide, WebAssembly) and pine2pyne off the main thread.
 *
 * Nothing here names a wheel file. public/wheels/manifest.json is generated by
 * scripts/prepare-static.mjs from whatever *.whl files are committed in public/wheels,
 * and every wheel listed there is unpacked into site-packages. No PyPI, no CDN. */
const BASE = new URL('./', self.location.href).href; // works under any GitHub Pages base path

const PYTHON = `
import json, time, warnings
import pine2pyne
from pine2pyne.errors import Pine2PyneError, SemanticWarning
from pine2pyne.di import get_transpiler  # builds the pipeline once, so the first click is fast

def convert(source, profile):
    started = time.perf_counter()
    result = {'ok': False, 'code': '', 'warnings': [], 'error': None}
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter('always')
        try:
            result['code'] = pine2pyne.transpile(source, profile=profile)
            result['ok'] = True
            if not result['code'].strip() and not pine2pyne._is_comment_only(source):
                result['ok'] = False
                result['error'] = {'kind': 'EmptyOutput', 'line': 0, 'column': 0,
                                   'message': 'the transpiler produced no output for this source'}
        except Pine2PyneError as error:
            result['error'] = {'kind': type(error).__name__, 'message': error.message,
                               'line': error.line, 'column': error.column}
        except RecursionError:
            result['error'] = {'kind': 'RecursionError', 'line': 0, 'column': 0,
                               'message': 'the script nests too deeply for the browser call stack; use the pine2pyne CLI'}
        except Exception as error:
            result['error'] = {'kind': type(error).__name__, 'message': str(error), 'line': 0, 'column': 0}
    for record in caught:
        w = record.message
        if isinstance(w, SemanticWarning):
            result['warnings'].append({'code': w.code, 'message': w.text, 'line': w.line, 'column': w.column})
    result['ms'] = round((time.perf_counter() - started) * 1000)
    return json.dumps(result)
`;

let convert = null;

async function boot() {
  const status = (message) => self.postMessage({ type: 'status', message });

  status('Loading the Python runtime');
  const manifest = await (await fetch(BASE + 'wheels/manifest.json', { cache: 'no-cache' })).json();
  importScripts(BASE + 'pyodide/pyodide.js');
  const pyodide = await self.loadPyodide({ indexURL: BASE + 'pyodide/' });

  status('Installing pine2pyne');
  const archives = await Promise.all(
    manifest.wheels.map(async (wheel) => {
      const response = await fetch(BASE + 'wheels/' + wheel.file);
      if (!response.ok) throw new Error(`${wheel.file}: HTTP ${response.status}`);
      return response.arrayBuffer();
    }),
  );
  for (const archive of archives) pyodide.unpackArchive(archive, 'wheel');

  status('Starting the transpiler');
  pyodide.runPython(PYTHON);
  convert = pyodide.globals.get('convert');

  self.postMessage({
    type: 'ready',
    pine2pyne: pyodide.runPython('pine2pyne.__version__'),
    python: pyodide.runPython('import platform; platform.python_version()'),
    pyodide: pyodide.version,
  });
}

const ready = boot().catch((error) => {
  self.postMessage({ type: 'fatal', message: String(error && error.message ? error.message : error) });
  throw error;
});

self.onmessage = async (event) => {
  const { id, source, profile } = event.data;
  try {
    await ready;
    self.postMessage({ type: 'result', id, result: JSON.parse(convert(source, profile)) });
  } catch (error) {
    self.postMessage({
      type: 'result',
      id,
      result: { ok: false, code: '', warnings: [], ms: 0,
        error: { kind: 'RuntimeError', message: String(error && error.message ? error.message : error), line: 0, column: 0 } },
    });
  }
};
